    "howrite.form.photoBody": "{hint} 然后写下你希望强调的特征。",
    "howrite.bagua.intro": "这是三钱《易经》法：六次投掷自下而上成一卦。你将在此逐步完成。",
    "howrite.bagua.1t": "心中只留一个问题",
    "howrite.bagua.1b": "古典做法：一事一卦。掷钱时把问题放在心里。",
    "howrite.bagua.2t": "三枚铜钱，掷六次",
    "howrite.bagua.2b": "每次投掷成一爻。正面=3，反面=2。和为 6／7／8／9 决定阴阳及是否动爻。",
    "howrite.bagua.3t": "自下而上叠爻",
    "howrite.bagua.3b": "初爻在下（开始）。上爻在顶（外貌）。六爻合成下卦与上卦。",
    "howrite.bagua.4t": "先读本卦，再看之卦",
