    "terms.title": "Términos de uso",
    "terms.updated": "Última actualización: 8 de octubre de 2026",
    "terms.intro": "Al usar Fatum Atlas aceptas estos términos. El sitio es un catálogo educativo y recreativo de métodos de adivinación con lecturas simuladas.",
    "terms.entertain.title": "Solo ocio y educación",
    "terms.entertain.body": "Ritos, lecturas, sellos y notas científicas son para jugar, cultura y reflexión. No son consejo profesional, profecía ni garantía de resultado.",
    "terms.decisions.title": "Tú tomas tus propias decisiones",
    "terms.decisions.body": "Eres el único responsable de cada elección tras usar el sitio. No te bases en un rito, suerte, carta, péndulo, carta natal u omen para asuntos médicos, legales, financieros, de seguridad, laborales o de relación.",
    "terms.noadvice.title": "No es consejo profesional",
    "terms.noadvice.body": "Nada aquí es consejo médico, psicológico, legal, fiscal, de inversión o de seguridad. Consulta a un profesional cualificado. No retrases ni rechaces atención real por una lectura.",
    "terms.liability.title": "Sin responsabilidad por los resultados",
    "terms.liability.body": "Las lecturas pueden ser inexactas, incompletas, aleatorias o sin sentido. El azar y los cisnes negros pueden cambiarlo todo. En la máxima medida permitida por la ley, Fatum Atlas y sus operadores no responden por pérdidas, daños o reclamaciones derivadas del uso del sitio o de actuar (o no) según un resultado.",
    "terms.education.title": "Simulaciones, no iniciación",
    "terms.education.body": "Los pasos guiados imitan descripciones públicas para aprender. No son práctica iniciática auténtica ni otorgan autoridad ritual.",
    "terms.data.title": "Datos en tu dispositivo",
    "terms.data.body": "Los sellos del diario y el idioma se guardan en este navegador. Las fotos se comprimen en local y no se suben a nuestros servidores. Borrar los datos del sitio las elimina.",
    "terms.accept.title": "Aceptación",
    "terms.accept.body": "Seguir usando el sitio implica aceptar estos términos. Si no estás de acuerdo, deja de usarlo. Si una parte no es aplicable, el resto sigue vigente.",
