    "howrite.omen.2t": "Reúne una señal",
    "howrite.omen.2b": "En la tradición pueden ser aves, humo, sueños, huellas u otros augurios. Aquí simulamos una señal en ese espíritu.",
    "howrite.omen.3t": "Interpreta con claridad",
    "howrite.omen.3b": "Explicamos la señal, la relacionamos con tu pregunta como un espejo y sugerimos notas reflexivas de hacer / no hacer — no un pronóstico de cisne negro."
