    "terms.eyebrow": "Mentions légales",
    "terms.title": "Conditions d’utilisation",
    "terms.updated": "Dernière mise à jour : 8 octobre 2026",
    "terms.intro": "En utilisant Fatum Atlas, vous acceptez ces conditions. Le site est un catalogue éducatif et ludique de méthodes divinatoires avec des lectures simulées.",
    "terms.entertain.title": "Divertissement et éducation seulement",
    "terms.entertain.body": "Rites, lectures, sceaux et notes scientifiques sont destinés au jeu, à la culture et à la réflexion — pas à un conseil professionnel, une prophétie ou une garantie.",
    "terms.decisions.title": "Vous prenez vos propres décisions",
    "terms.decisions.body": "Vous restez seul responsable de chaque choix après usage du site. Ne vous fiez pas à un rite, un sort, une carte, un pendule ou un présage pour des questions médicales, juridiques, financières, de sécurité, d’emploi ou relationnelles.",
    "terms.noadvice.title": "Aucun conseil professionnel",
    "terms.noadvice.body": "Rien ici n’est un conseil médical, psychologique, juridique, fiscal, d’investissement ou de sécurité. Consultez un professionnel qualifié. Ne retardez pas des soins réels à cause d’une lecture.",
    "terms.liability.title": "Aucune responsabilité pour les résultats",
    "terms.liability.body": "Les lectures peuvent être inexactes, incomplètes, aléatoires ou vides de sens. Hasard et cygnes noirs peuvent tout changer. Dans la plus large mesure permise par la loi, Fatum Atlas et ses opérateurs ne sont pas responsables des pertes, dommages ou réclamations liés à l’usage du site ou à une décision basée sur un résultat.",
    "terms.education.title": "Simulations, pas d’initiation",
    "terms.education.body": "Les étapes guidées imitent des descriptions publiques à des fins d’apprentissage. Ce n’est pas une pratique initiatique authentique.",
    "terms.data.title": "Données sur votre appareil",
    "terms.data.body": "Sceaux du journal et langue restent dans ce navigateur. Les photos sont compressées localement et ne sont pas envoyées à nos serveurs.",
    "terms.accept.title": "Acceptation",
