    "howrite.thisRite": "ce rite",
    "howrite.where": " · {place}",
    "howrite.note": "Jeu éducatif sur ce site — pas un substitut à une pratique initiatique formée, ni à la médecine, au droit ou au jugement de sécurité.",
    "howrite.form.photoBody": "{hint} Ensuite, écrivez le trait à souligner.",
    "howrite.bagua.intro": "C’est la méthode des trois pièces du Yijing : six lancers construisent un hexagramme de bas en haut. Vous le jouerez pas à pas.",
    "howrite.bagua.1t": "Gardez une question claire",
    "howrite.bagua.1b": "Usage classique : une affaire par hexagramme. Gardez-la en tête pendant les lancers.",
    "howrite.bagua.2t": "Lancez trois pièces, six fois",
    "howrite.bagua.2b": "Chaque lancer fait une ligne. Face = 3, pile = 2. Les sommes 6 / 7 / 8 / 9 décident yin ou yang, et si la ligne mute.",
    "howrite.bagua.3t": "Empilez les lignes de bas en haut",
    "howrite.bagua.3b": "La ligne 1 est le bas (début). La 6 est le haut (face externe). Ensemble elles forment deux trigrammes — inférieur et supérieur.",
    "howrite.bagua.4t": "Lisez le primaire, puis le changement",
    "howrite.bagua.4b": "Si une ligne mute (6 ou 9), lisez d’abord l’hexagramme primaire (présent), puis la figure transformée (direction du changement).",
    "howrite.bagua.5t": "Recevez une lecture en langage clair",
    "howrite.bagua.5b": "Nous expliquons les symboles, les relions à votre question comme un miroir, et proposons des notes à envisager de faire / de ne pas faire — pas une prévision garantie.",
    "howrite.tarot.intro": "Un tirage de trois Arcanes majeurs. Seules les 22 grandes cartes archétypales sont utilisées (Le Mat jusqu’au Monde).",
    "howrite.tarot.1t": "Nommez ce que vous cherchez",
    "howrite.tarot.1b": "Les questions ouvertes marchent le mieux. Le oui/non strict est en général trop étroit pour le tarot.",
    "howrite.tarot.2t": "Mélangez et coupez",
    "howrite.tarot.2b": "Le jeu est mélangé avec votre question. Vous coupez une fois ; trois cartes sont mises de côté : Passé · Présent · Voie.",
    "howrite.tarot.3t": "Révélez une carte à la fois",
    "howrite.tarot.3b": "Chaque carte peut être droite ou renversée. Vous retournez Passé, puis Présent, puis Voie, pour que l’histoire se construise dans l’ordre.",
    "howrite.tarot.4t": "Lisez l’histoire ensemble",
    "howrite.tarot.4b": "Nous expliquons chaque carte, les tissons à votre question et proposons des notes réflexives faire / ne pas faire. Les cartes sont aléatoires ; les sens sont symboliques.",
    "howrite.mbti.intro": "Un court questionnaire de préférences inspiré du MBTI. Il décrit comment vous tendez à porter attention au monde — pas l’aptitude, la valeur ni un destin fixe.",
    "howrite.mbti.1t": "Thème facultatif",
    "howrite.mbti.1b": "Vous pouvez nommer un domaine (travail, relation, voie créative) pour que le conseil final s’y adresse.",
    "howrite.mbti.2t": "Répondez à 12 choix forcés",
    "howrite.mbti.2b": "Chaque item choisit un côté d’une paire : E/I (énergie), S/N (information), T/F (décisions), J/P (mode de vie).",
    "howrite.mbti.3t": "Comptez vos quatre lettres",
    "howrite.mbti.3b": "Les majorités de chaque paire deviennent un code de type (par exemple ENFP). Les égalités penchent d’un côté pour un code net.",
    "howrite.mbti.4t": "Note de chemin réflexive",
    "howrite.mbti.4b": "Vous obtenez une explication claire du schéma et des invites faire / ne pas faire. C’est une autodescription pour réfléchir — pas une prévision d’événements.",
    "howrite.ifa.intro": "Ifá est une tradition oraculaire yoruba. Ici vous jouez une simulation éducative de sorts — pas une initiation de babaláwo ni une vraie consultation d’Odù.",
    "howrite.ifa.1t": "Gardez votre question",
    "howrite.ifa.1b": "Nommez l’affaire sur laquelle vous voulez conseil. Dans la pratique vivante, un prêtre formé lancerait et réciterait des vers ; ici nous simulons le tirage pour apprendre.",
    "howrite.ifa.2t": "Tirez au sort",
    "howrite.ifa.2b": "Traditionnellement des noix de palme ou une chaîne ọ̀pẹ̀lẹ̀ donnent l’un des 256 Odù. Cette appli pose une figure symbolique dans cet esprit.",
    "howrite.ifa.3t": "Lisez la figure clairement",
    "howrite.ifa.3b": "Nous expliquons ce qui est apparu, comment le lire comme miroir de votre question, et des notes faire / ne pas faire — clairement étiquetées comme éducatives.",
