    "terms.updated": "آخر تحديث: 8 أكتوبر 2026",
    "terms.intro": "باستخدامك Fatum Atlas فإنك توافق على هذه الشروط. الموقع كتالوج تعليمي وترفيهي لطرق العرافة مع قراءات محاكاة.",
    "terms.entertain.title": "للترفيه والتعليم فقط",
    "terms.entertain.body": "الطقوس والقراءات والأختام والملاحظات العلمية للعب والثقافة والتأمل، وليست نصيحة مهنية أو نبوءة أو ضمانًا لأي نتيجة.",
    "terms.decisions.title": "أنت تتخذ قراراتك بنفسك",
    "terms.decisions.body": "تتحمل وحدك مسؤولية كل اختيار بعد استخدام الموقع. لا تعتمد على طقس أو قرعة أو بطاقة أو بندول أو فأل في أمور طبية أو قانونية أو مالية أو أمنية أو مهنية أو عاطفية.",
    "terms.noadvice.title": "ليست نصيحة مهنية",
    "terms.noadvice.body": "لا شيء هنا نصيحة طبية أو نفسية أو قانونية أو ضريبية أو استثمارية أو أمنية. استشر مختصًا مؤهلاً. لا تؤخر الرعاية الحقيقية بسبب قراءة.",
    "terms.liability.title": "لا مسؤولية عن نتائج الطقوس",
    "terms.liability.body": "قد تكون القراءات غير دقيقة أو عشوائية. إلى أقصى حد يسمح به القانون، Fatum Atlas ومشغّلوه غير مسؤولين عن أي خسارة أو ضرر ناتج عن استخدام الموقع أو التصرف وفق نتيجة.",
