    "sources.eyebrow": "श्रेय",
    "sources.title": "अनुष्ठानों के स्रोत",
    "sources.copy": "सीखने के लिए सांस्कृतिक संदर्भ — पवित्र दीक्षा मैनुअल नहीं।",
    "footer.tag": "खेलें · चिंतन · संग्रह — भविष्यवाणी नहीं। डेक में काला हंस नहीं।",
    "footer.legal": "निर्णय आप स्वयं लेते हैं। हम अनुष्ठान परिणामों या उसके बाद आपके कार्यों के लिए उत्तरदायी नहीं हैं।",
    "terms.eyebrow": "कानूनी",
    "terms.title": "उपयोग की शर्तें",
    "terms.updated": "अंतिम अद्यतन: 8 अक्टूबर 2026",
    "terms.intro": "Fatum Atlas का उपयोग करके आप इन शर्तों से सहमत होते हैं। यह शैक्षिक-मनोरंजक सूची है, पठन सिम्युलेटेड हैं।",
    "terms.entertain.title": "केवल मनोरंजन और शिक्षा",
    "terms.entertain.body": "अनुष्ठान, पठन और नोट्स खेल, संस्कृति और चिंतन के लिए हैं — पेशेवर सलाह या भविष्यवाणी नहीं।",
    "terms.decisions.title": "निर्णय आप स्वयं लेते हैं",
    "terms.decisions.body": "साइट के बाद हर चुनाव की ज़िम्मेदारी आपकी है। चिकित्सा, कानूनी, वित्तीय या सुरक्षा मामलों के लिए पठन पर निर्भर न करें।",
    "terms.noadvice.title": "पेशेवर सलाह नहीं",
    "terms.noadvice.body": "यहाँ कुछ भी चिकित्सा, कानूनी या वित्तीय सलाह नहीं है। योग्य विशेषज्ञ से मिलें।",
    "terms.liability.title": "परिणामों के लिए कोई दायित्व नहीं",
    "terms.liability.body": "पठन गलत या यादृच्छिक हो सकते हैं। कानून की अधिकतम सीमा तक Fatum Atlas परिणामों से होने वाले नुकसान के लिए उत्तरदायी नहीं है।",
    "terms.education.title": "सिमुलेशन, दीक्षा नहीं",
    "terms.education.body": "निर्देशित चरण सीखने के लिए सार्वजनिक विवरणों की नकल हैं, प्रामाणिक दीक्षा नहीं।",
    "terms.data.title": "डेटा आपके उपकरण पर",
    "terms.data.body": "जर्नल और भाषा इस ब्राउज़र में रहती है। फ़ोटो स्थानीय रूप से संपीड़ित होते हैं, हमारे सर्वर पर नहीं भेजे जाते।",
    "terms.accept.title": "स्वीकृति",
    "terms.accept.body": "जारी उपयोग इन शर्तों की स्वीकृति है। असहमति हो तो उपयोग बंद करें।",
