    "studio.form.privacy": "फ़ोटो केवल इसी ब्राउज़र में रहती हैं (पाठ और डायरी के लिए संकुचित)। सर्वर पर कुछ नहीं भेजा जाता।",
    "studio.form.needImage": "कृपया छवि फ़ाइल चुनें (JPG, PNG, WEBP आदि)।",
    "studio.form.readFail": "वह छवि पढ़ी नहीं जा सकी। दूसरी फ़ोटो आज़माएँ।",
    "studio.form.refPhoto": "संदर्भ फ़ोटो",
    "studio.form.submittedPhoto": "इस पाठ के लिए दी गई फ़ोटो",
    "process.cta.birth": "मेरा भाग्य पढ़ें",
