    "process.cta.form": "रूप पढ़ें",
    "process.cta.pendulum": "लोलक से पूछें",
    "process.cta.day": "इस दिन की जाँच करें",
    "process.cta.omen": "शकुन खोजें",
    "process.ritual.birth": "आकाश का चार्ट बन रहा है…",
    "process.ritual.cast": "डाला जा रहा है…",
