    "howrite.thisRite": "este rito",
    "howrite.where": " · {place}",
    "howrite.note": "Jogo educativo neste site — não substitui prática iniciática treinada, medicina, direito ou juízo de segurança.",
    "howrite.form.photoBody": "{hint} Depois escreva o traço que quer destacar.",
    "howrite.bagua.intro": "Este é o método das três moedas do Yijing: seis lançamentos montam um hexagrama de baixo para cima. Você o jogará passo a passo.",
    "howrite.bagua.1t": "Segure uma pergunta clara",
    "howrite.bagua.1b": "Prática clássica: um assunto por hexagrama. Mantenha-o em mente ao lançar.",
    "howrite.bagua.2t": "Lance três moedas, seis vezes",
    "howrite.bagua.2b": "Cada lançamento faz uma linha. Cara = 3, coroa = 2. As somas 6 / 7 / 8 / 9 decidem yin ou yang e se muda.",
    "howrite.bagua.3t": "Empilhe as linhas de baixo para cima",
    "howrite.bagua.3b": "A linha 1 é a de baixo (início). A 6 é a de cima (face externa). Juntas formam dois trigramas — inferior e superior.",
    "howrite.bagua.4t": "Leia o primário, depois a mudança",
    "howrite.bagua.4b": "Se alguma linha muda (6 ou 9), leia primeiro o hexagrama primário (presente) e depois a figura transformada (direção da mudança).",
    "howrite.bagua.5t": "Receba uma leitura em linguagem clara",
    "howrite.bagua.5b": "Explicamos os símbolos, relacionamos à sua pergunta como um espelho e oferecemos notas de considerar fazer / não fazer — não uma previsão garantida.",
    "howrite.tarot.intro": "Uma tiragem de três Arcanos Maiores. Só as 22 cartas arquetípicas (O Louco até O Mundo).",
    "howrite.tarot.1t": "Diga o que busca",
    "howrite.tarot.1b": "Perguntas abertas funcionam melhor. Sim/não rígido costuma ser estreito demais para o tarô.",
    "howrite.tarot.2t": "Embaralhe e corte",
    "howrite.tarot.2b": "O baralho é embaralhado com sua pergunta. Você corta uma vez; três cartas ficam como Passado · Presente · Caminho.",
    "howrite.tarot.3t": "Revele uma carta de cada vez",
    "howrite.tarot.3b": "Cada carta pode estar direita ou invertida. Você vira Passado, depois Presente, depois Caminho, e a história se monta em ordem.",
    "howrite.tarot.4t": "Leia a história em conjunto",
    "howrite.tarot.4b": "Explicamos o sentido de cada carta, tecemos com sua pergunta e sugerimos notas reflexivas de fazer / não fazer. As cartas são aleatórias; os sentidos, simbólicos.",
    "howrite.mbti.intro": "Um questionário curto de preferências inspirado no MBTI. Descreve como você tende a atender ao mundo — não habilidade, valor nem um destino fixo.",
    "howrite.mbti.1t": "Foco opcional",
    "howrite.mbti.1b": "Você pode nomear uma área (trabalho, relação, via criativa) para o conselho final falar dela.",
    "howrite.mbti.2t": "Responda 12 escolhas forçadas",
    "howrite.mbti.2b": "Cada item escolhe um lado de um par: E/I (energia), S/N (informação), T/F (decisões), J/P (estilo de vida).",
    "howrite.mbti.3t": "Some suas quatro letras",
    "howrite.mbti.3b": "As maiorias de cada par viram um código de tipo (por exemplo ENFP). Empates pendem a um lado para um código limpo.",
    "howrite.mbti.4t": "Nota de caminho reflexiva",
    "howrite.mbti.4b": "Você recebe uma explicação clara do padrão e avisos no estilo fazer / não fazer. É autodescrição para reflexão — não previsão de eventos.",
    "howrite.ifa.intro": "Ifá é uma tradição oracular iorubá. Neste site você joga uma simulação educativa de sortes — não iniciação de babaláwo nem consulta real de Odù.",
    "howrite.ifa.1t": "Segure sua pergunta",
    "howrite.ifa.1b": "Nomeie o assunto sobre o qual quer conselho. Na prática viva, um sacerdote treinado lançaria e recitaria versos; aqui simulamos o lance para aprender.",
    "howrite.ifa.2t": "Lance as sortes",
    "howrite.ifa.2b": "Tradicionalmente nozes de palma ou uma corrente ọ̀pẹ̀lẹ̀ produzem um dos 256 Odù. Este app fixa uma figura simbólica nesse espírito.",
    "howrite.ifa.3t": "Leia a figura com clareza",
    "howrite.ifa.3b": "Explicamos o que apareceu, como lê-lo como espelho da sua pergunta e notas de fazer / não fazer — claramente marcadas como educativas.",
    "howrite.birth.intro": "{name}{where} monta uma assinatura de nascimento simbólica a partir de uma data.{bit}",
    "howrite.birth.1t": "Informe uma data de nascimento",
    "howrite.birth.1b": "Use sua data (ou outra que tenha permissão para explorar). Opcional: acrescente um foco.",
    "howrite.birth.2t": "Derive rótulos no estilo da tradição",
    "howrite.birth.2b": "Calculamos tags calendáricos / zodiacais simplificados no espírito deste método (não um mapa profissional completo).",
    "howrite.birth.3t": "Leia como um espelho",
    "howrite.birth.3b": "Você recebe o que foi calculado, o que isso sugere tradicionalmente como símbolo e notas de fazer / não fazer — não uma previsão científica.",
