    "howrite.dice.2b": "Faces de dados ou ossos são lançadas (simulado aqui).",
    "howrite.dice.3t": "Interprete os números",
    "howrite.dice.3b": "Explicamos as faces/soma como uma inclinação simbólica e relacionamos à sua pergunta sem inventar profecias datadas.",
