    "howrite.form.3t": "Leitura de forma reflexiva",
    "howrite.form.3b": "Tratamos suas notas (e a foto, se houver) como aberturas de conversa. Não é diagnóstico médico nem ciência do destino comprovada.",
    "howrite.pendulum.intro": "{name}{where} responde uma pergunta sim/não com um balanço.{bit}",
    "howrite.pendulum.1t": "Faça uma pergunta sim/não de verdade",
