    "howrite.dice.3t": "Истолкуйте числа",
    "howrite.dice.3b": "Мы объясняем грани/сумму как символический наклон и связываем с вопросом, не выдумывая датированных пророчеств.",
    "howrite.book.intro": "{name}{where} открывает текст будто наугад и читает строку рядом с вопросом.{bit}",
    "howrite.book.1t": "Держите вопрос",
    "howrite.book.1b": "Назовите, рядом с чем должна лечь открытая строка.",
    "howrite.book.2t": "Откройте страницу",
    "howrite.book.2b": "Выбирается стих или жребий (имитация библиомантии).",
    "howrite.book.3t": "Пусть строка говорит как подсказка",
    "howrite.book.3b": "Мы объясняем выпавшую строку и как использовать её как размышление — не буквальное пророчество.",
    "howrite.form.intro": "{name}{where} читает видимую форму.{bit}",
    "howrite.form.1t": "Отметьте, что видите",
    "howrite.form.1b": "Опишите главную черту или наблюдение, которое нужно прочесть.",
    "howrite.form.2t": "Назовите тему",
    "howrite.form.2b": "Карьера, характер, отношения, интерес к здоровью и т. д. — чтобы совет имел цель.",
    "howrite.form.3t": "Рефлексивное чтение формы",
    "howrite.form.3b": "Мы берём ваши заметки (и фото, если есть) как зачин разговора. Это не меддиагноз и не доказанная наука судьбы.",
    "howrite.pendulum.intro": "{name}{where} отвечает на да/нет качанием.{bit}",
    "howrite.pendulum.1t": "Задайте настоящий вопрос да/нет",
    "howrite.pendulum.1b": "О том, на что вы можете повлиять. Избегайте составных вопросов («Уволиться и уехать за границу?»).",
    "howrite.pendulum.2t": "Следите за качанием",
    "howrite.pendulum.2b": "Имитация маятника даёт да или нет (с мягким/ясным/сильным наклоном).",
    "howrite.pendulum.3t": "Заметьте свою реакцию",
    "howrite.pendulum.3b": "Мы объясняем, что идеомоторное движение может качать настоящие маятники. Ответ — повод заметить смещение, не доказательство о мире.",
    "howrite.day.intro": "{name}{where} проверяет, благоприятна ли дата для цели.{bit}",
    "howrite.day.1t": "Выберите дату и цель",
    "howrite.day.1b": "Поездка, подписание, обряд, общие дела — будьте конкретны.",
    "howrite.day.2t": "Сверьтесь с наклоном календаря",
    "howrite.day.2b": "Мы показываем традиционный благоприятный / смешанный / неблагоприятный наклон для учёбы (не астрономическая гарантия).",
    "howrite.day.3t": "Планируйте и по обычным свидетельствам",
    "howrite.day.3b": "Логистику, безопасность и обязательства всё равно держите на реальных проверках.",
    "howrite.omen.intro": "{name}{where} следит за знаками в своём символическом поле.{bit}",
