    "howrite.omen.2t": "兆しを集める",
    "howrite.omen.2b": "伝統では鳥、煙、夢、足跡などの兆しです。ここではその精神で兆しを模擬します。",
    "howrite.omen.3t": "平易に解釈する",
    "howrite.omen.3b": "兆しを説明し、問いの鏡としてつなぎ、やってみる／控えるメモを出します。黒鳥の予報ではありません。"
