    "terms.intro": "Khi dùng Fatum Atlas bạn đồng ý với các điều khoản này. Đây là catalog giáo dục, giải trí với bài đọc mô phỏng.",
    "terms.entertain.title": "Chỉ để giải trí và học hỏi",
    "terms.entertain.body": "Nghi thức, bài đọc và ghi chú dành cho chơi, văn hóa và suy ngẫm — không phải tư vấn chuyên môn, lời tiên tri hay bảo đảm kết quả.",
    "terms.decisions.title": "Bạn tự quyết định",
    "terms.decisions.body": "Mọi lựa chọn sau khi dùng trang là trách nhiệm của bạn. Đừng dựa vào nghi thức, bài, con lắc hay điềm để quyết định y tế, pháp lý, tài chính hay an toàn.",
    "terms.noadvice.title": "Không phải tư vấn chuyên môn",
    "terms.noadvice.body": "Không có tư vấn y tế, pháp lý hay đầu tư ở đây. Hãy gặp chuyên gia có thẩm quyền.",
    "terms.liability.title": "Không chịu trách nhiệm về kết quả",
    "terms.liability.body": "Bài đọc có thể sai hoặc ngẫu nhiên. Trong phạm vi pháp luật cho phép, Fatum Atlas không chịu trách nhiệm tổn thất từ việc dùng trang hoặc hành động theo kết quả.",
    "terms.education.title": "Mô phỏng, không phải khai tâm",
    "terms.education.body": "Các bước hướng dẫn bắt chước mô tả công khai để học, không phải thực hành khai tâm chân thực.",
